import sys

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return

    # Skip the first line (index 0)
    for line in lines[1:]:
        ans = 0
        arr = line.split(' ')

        for word in arr:
            curr = 0
            for char in word:
                if 'A' <= char <= 'Z':
                    curr += 1
            ans = max(ans, curr)

        print(ans)

if __name__ == "__main__":
    main()

