const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
  terminal: false
});
let c = 0;

rl.on('line', (str) => {
  if (c === 0) {
    c++;
    return;
  }

  let ans = 0;
  const arr = str.split(' ');

  for (let i = 0; i < arr.length; i++) {
    let curr = 0;

    for (let j = 0; j < arr[i].length; j++) {
      if (arr[i].charCodeAt(j) >= 65 && arr[i].charCodeAt(j) <= 90) {
        curr++;
      }
    }

    ans = Math.max(ans, curr);
  }

  console.log(ans);

  c++;
});
